// mh-dumpdag — dumps the cache and the dataset as binary fixtures for the CUDA test (F3).
//
//	mh-dumpdag <directory> [epoch]
//
// It writes `cache.bin` and `randmath.txt`; in the test profile also `dataset.bin` (8 MiB), in
// the mainnet profile `spotcheck.txt` instead — a 1 GiB reference would take needlessly long to
// transfer, so spot checks scattered across the whole range of indices, including the edges,
// are used.
//
// The words are little-endian uint32. The fixtures do not belong in the repo — they are
// generated by the test. The mainnet profile is turned on with the MH_MAINNET variable.
package main

import (
	"bufio"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strconv"

	"powmachina/internal/mh"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: mh-dumpdag <directory> [epoch]")
		os.Exit(2)
	}
	dir := os.Args[1]
	var epoch uint64
	if len(os.Args) > 2 {
		n, err := strconv.ParseUint(os.Args[2], 10, 64)
		if err != nil {
			die(fmt.Errorf("epoch: %w", err))
		}
		epoch = n
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		die(err)
	}

	_, mainnet := os.LookupEnv("MH_MAINNET")
	params := mh.TestDag(epoch)
	profile := "test"
	if mainnet {
		params = mh.MainnetDag(epoch)
		profile = "mainnet"
	}

	cache := mh.BuildCache(params)
	fmt.Printf("profile %s, epoch %d: cache %d items, dataset %d items\n",
		profile, epoch, params.CacheItems(), params.DatasetItems())
	writeWords(filepath.Join(dir, "cache.bin"), cache.Words())

	// The epoch's RANDMATH sequence — the kernel is given it as a constant, it does not derive it itself.
	ops := mh.NewRandMath(epoch).OpsRaw()
	var rm []byte
	for _, o := range ops {
		rm = append(rm, fmt.Sprintf("%d %d %d\n", o[0], o[1], o[2])...)
	}
	if err := os.WriteFile(filepath.Join(dir, "randmath.txt"), rm, 0o644); err != nil {
		die(err)
	}
	fmt.Printf("RANDMATH: %d operations → randmath.txt\n", len(ops))

	if !mainnet {
		dag := mh.BuildFullDagFrom(cache)
		writeWords(filepath.Join(dir, "dataset.bin"), dag.Words())
		return
	}

	n := params.DatasetItems()
	idxs := []int{0, 1, 2, n / 2, n - 2, n - 1}
	x := uint64(0x9E3779B97F4A7C15)
	for range 58 {
		x ^= x << 13
		x ^= x >> 7
		x ^= x << 17
		idxs = append(idxs, int(x%uint64(n)))
	}
	light := mh.NewLightDagFrom(cache)
	f, err := os.Create(filepath.Join(dir, "spotcheck.txt"))
	if err != nil {
		die(err)
	}
	defer f.Close()
	w := bufio.NewWriter(f)
	var item [mh.DagItemWords]uint32
	buf := make([]byte, mh.DagItemBytes)
	for _, i := range idxs {
		light.ItemInto(i, &item)
		for k, v := range item {
			binary.LittleEndian.PutUint32(buf[k*4:], v)
		}
		fmt.Fprintf(w, "%d %s\n", i, hex.EncodeToString(buf))
	}
	if err := w.Flush(); err != nil {
		die(err)
	}
	fmt.Printf("%d spot checks → spotcheck.txt\n", len(idxs))
}

func writeWords(path string, words []uint32) {
	f, err := os.Create(path)
	if err != nil {
		die(err)
	}
	defer f.Close()
	w := bufio.NewWriter(f)
	var b [4]byte
	for _, x := range words {
		binary.LittleEndian.PutUint32(b[:], x)
		if _, err := w.Write(b[:]); err != nil {
			die(err)
		}
	}
	if err := w.Flush(); err != nil {
		die(err)
	}
	fmt.Printf("%s — %d B\n", path, len(words)*4)
}

func die(err error) {
	fmt.Fprintln(os.Stderr, err)
	os.Exit(1)
}
